package dev.falix.studiomobile;
import android.app.*;import android.content.*;import android.os.*;import android.net.Uri;import org.json.*;import java.io.*;import java.util.*;import java.util.zip.*;
/** Tests real on-device files; QA-created projects are labeled and removed. No live upload. */
public final class ProjectQa extends NativeQa {
 @Override public void onStart(){Bundle result=new Bundle();ArrayList<ManagedProjects.Record> cleanup=new ArrayList<>();try{
  Context target=getTargetContext();target.getSharedPreferences("settings",0).edit().putBoolean("setupStarted",true).putBoolean("setupDone",true).putBoolean("compactUi",true).putBoolean("reduceMotion",true).putString("appearance","dark").remove("projectTree").commit();new CredentialVault(target).clear();app=(MainActivity)startActivitySync(new Intent(target,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));directory=new File(target.getExternalFilesDir(null),"qa030");directory.mkdirs();pause(1800);ManagedProjects repo=app.projectUi.repo;
  assertTrue(Class.forName("org.yaml.snakeyaml.Yaml")!=null,"Real safe YAML parser bundled");
  for(String mode:new String[]{"light","dark"}){ui(()->app.setAppearance(mode));ui(()->app.navigate("new-project"));capture(mode+"-create-project");ui(()->((android.widget.ScrollView)app.content.getParent()).fullScroll(android.view.View.FOCUS_DOWN));capture(mode+"-create-options");ui(()->((android.widget.ScrollView)app.content.getParent()).scrollTo(0,0));}
  // Use the actual form's submit action rather than creating only via repository.
  ui(()->{app.projectUi.nameField.setText("QA · Mobile workshop");app.projectUi.descriptionField.setText("Test-only native project creation.");app.projectUi.startField.setText("Start place");app.projectUi.submit(false);});for(int n=0;n<100&&(!app.screen.equals("project")||app.projectUi.working);n++)pause(200);assertTrue("project".equals(app.screen)&&app.projectUi.selected!=null,"Native Create action creates and opens a persisted project");ManagedProjects.Record r=repo.load(app.projectUi.selected.folder);cleanup.add(r);
  assertTrue(repo.child(r.folder,"project.yml")!=null&&r.places().length()==1,"Created project.yml plus one start place");JSONObject start=r.places().getJSONObject(0);byte[] place=repo.bytes(repo.placeUri(r,start),1024*1024);String xml=new String(place,"UTF-8");assertTrue(xml.contains("class=\"Workspace\"")&&xml.contains("class=\"Part\"")&&xml.contains("class=\"SpawnLocation\""),"Baseplate contains real Workspace, baseplate Part and SpawnLocation");javax.xml.parsers.DocumentBuilderFactory factory=javax.xml.parsers.DocumentBuilderFactory.newInstance();factory.setExpandEntityReferences(false);org.w3c.dom.Document parsed=factory.newDocumentBuilder().parse(new ByteArrayInputStream(place));assertTrue("4".equals(parsed.getDocumentElement().getAttribute("version")),"Generated place is well-formed Roblox XML version 4");assertTrue(start.getString("sha256").equals(ManagedProjects.hash(place)),"Place hash matches actual file contents");
  repo.addPlace(r,"QA · Lobby","empty");assertTrue(repo.load(r.folder).places().length()==2,"Add place persists a second distinct .rbxlx");app.projectUi.selected=r;ui(()->app.navigate("project"));capture("dark-multiple-places");JSONObject lobby=r.places().getJSONObject(1);assertTrue(!new String(repo.bytes(repo.placeUri(r,lobby),1024*1024),"UTF-8").contains("class=\"Part\""),"Empty template is actually empty of template parts");
  // Export and preserve one labeled sample for source/delivery validation.
  File export=repo.export(r);try(ZipFile zip=new ZipFile(export)){assertTrue(zip.getEntry("project.yml")!=null&&zip.getEntry(start.getString("file"))!=null&&zip.getEntry(lobby.getString("file"))!=null,"ZIP export contains YAML and both real place files");}copy(export,new File(directory,"QA-created-sample.zip"));File hostile=new File(target.getCacheDir(),"unsafe.zip");try(ZipOutputStream z=new ZipOutputStream(new FileOutputStream(hostile))){repo.zipEntry(z,"project.yml",ManagedProjects.yaml(r.data).getBytes("UTF-8"));repo.zipEntry(z,"../outside.txt",new byte[]{1});}boolean zipRejected=false;try{repo.importZip(hostile);}catch(Exception expected){zipRejected=true;}hostile.delete();assertTrue(zipRejected,"Project ZIP import rejects unsafe/unknown paths");boolean yamlRejected=false;try{ManagedProjects.parse("!!java.util.Date {}".getBytes("UTF-8"));}catch(Exception expected){yamlRejected=true;}assertTrue(yamlRejected,"Safe YAML loader rejects arbitrary Java object tags");ManagedProjects.Record restored=repo.importZip(export);cleanup.add(restored);assertTrue(restored.places().length()==2&&restored.data.optJSONObject("cloud").optLong("universe_id",0)==0,"Project ZIP import restores actual place files and clears cloud links");export.delete();
  ManagedProjects.Record duplicate=repo.duplicate(r);cleanup.add(duplicate);assertTrue(!duplicate.data.getString("id").equals(r.data.getString("id"))&&duplicate.data.optJSONObject("cloud").optLong("universe_id",0)==0,"Duplicate creates independent project without cloud links");
  File replacement=new File(target.getCacheDir(),"replacement.rbxlx");try(FileOutputStream out=new FileOutputStream(replacement)){out.write(PlaceTemplate.generate("Replacement","empty",100,true).getBytes("UTF-8"));}repo.replace(r,lobby,replacement);replacement.delete();assertTrue(new String(repo.bytes(repo.placeUri(r,lobby),1024*1024),"UTF-8").contains("<float name=\"Gravity\">100.0</float>"),"Replace writes real content and updates manifest hash");assertTrue(repo.child(r.folder,"backups")!=null,"Replacement backup directory exists");
  boolean protectedStart=false;try{repo.removePlace(r,start);}catch(IOException expected){protectedStart=true;}assertTrue(protectedStart,"Start place cannot be removed before choosing another");repo.removePlace(r,lobby);assertTrue(repo.load(r.folder).places().length()==1,"Remove place updates manifest while keeping the start place");
  boolean invalid=false;try{ManagedProjects.validate("",Collections.emptyList(),0,Double.NaN);}catch(IOException expected){invalid=true;}assertTrue(invalid,"Invalid name, devices and options are rejected");
  ManagedProjects.Record portable=repo.load(r.folder);portable.places().getJSONObject(0).put("file","places/../../outside.rbxlx");boolean escaped=false;try{repo.save(portable);}catch(Exception expected){escaped=true;}assertTrue(escaped,"Manifest paths cannot escape the project places folder");r=repo.load(r.folder);
  File staged=repo.stage(r,r.places().getJSONObject(0));okhttp3.Request saved=PublishService.request("test-only-key",123,456,staged,false),published=PublishService.request("test-only-key",123,456,staged,true);assertTrue(saved.url().toString().endsWith("versionType=Saved")&&published.url().toString().endsWith("versionType=Published")&&"application/xml".equals(saved.body().contentType().toString()),"Publish request sends actual XML file to correct Saved/Published endpoint");assertTrue(PublishService.parse("{\"versionNumber\":7}",true).version==7,"Only Roblox versionNumber confirms upload success");boolean unconfirmed=false;try{PublishService.parse("{}",true);}catch(IOException expected){unconfirmed=true;}assertTrue(unconfirmed,"A success body without versionNumber cannot fake publication");staged.delete();
  app.projectUi.selected=r;for(String mode:new String[]{"light","dark"}){ui(()->app.setAppearance(mode));ui(()->app.navigate("project"));capture(mode+"-project-detail");ui(()->app.navigate("project-settings"));capture(mode+"-project-settings");ui(()->app.navigate("projects"));pause(1600);capture(mode+"-projects-compact");ui(()->app.navigate("login"));capture(mode+"-login-compact");}
  // Public thumbnail request and real decode, with no creator credential or account fixture.
  RobloxApi.Experience image=new RobloxApi.Experience(10769969151L,"User-provided universe",107845908440922L);app.api.resolveIcon(image);report.add("THUMBNAIL: supplied universe returned "+image.iconState+"; image URL available="+!image.icon.isEmpty());if(!image.icon.isEmpty()){android.graphics.Bitmap bmp=app.api.image(image.icon,128);assertTrue(bmp!=null,"Real Roblox thumbnail bytes decode through new image transport");try(OutputStream out=new FileOutputStream(new File(directory,"roblox-thumbnail.png"))){bmp.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}bmp.recycle();}
  assertTrue(!RobloxApi.imageHost(new java.net.URL("http://rbxcdn.com/x"))&&!RobloxApi.imageHost(new java.net.URL("https://rbxcdn.com.evil.example/x")),"Image redirects reject insecure and look-alike hosts");
  for(ManagedProjects.Record item:cleanup)repo.deleteUri(item.folder);cleanup.clear();assertTrue(repo.child(r.folder,"project.yml")==null,"Local delete removes QA project without cloud actions");ui(()->{app.projectUi.selected=null;app.navigate("projects");});pause(1600);capture("dark-projects-empty");
  report.add("DEVICE: Android "+Build.VERSION.RELEASE+" / API "+Build.VERSION.SDK_INT);report.add("SAMPLES: QA-created local project only, not an actual cloud experience.");report.add("NOT VERIFIED: desktop Studio load/playtest; live Saved/Published upload; modern Android permission flows; SAF provider end-to-end UI.");try(PrintWriter out=new PrintWriter(new File(directory,"project-qa-report.txt"))){for(String line:report)out.println(line);}result.putString("report",String.join("\n",report));finish(Activity.RESULT_OK,result);
 }catch(Throwable e){try{if(app!=null)for(ManagedProjects.Record r:cleanup)app.projectUi.repo.deleteUri(r.folder);}catch(Exception ignored){}result.putString("error",e.toString());try{if(directory!=null)try(PrintWriter out=new PrintWriter(new File(directory,"error.txt"))){e.printStackTrace(out);}}catch(Exception ignored){}finish(Activity.RESULT_CANCELED,result);}}
 void copy(File source,File target)throws Exception{try(InputStream in=new FileInputStream(source);OutputStream out=new FileOutputStream(target)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}}
}
